// Prompts of the Pauta build team. Written for the Linux PC; adapted to Windows on 2026-10-27.
// The Windows session has no workflow runner: the lead launches each agent with the Agent tool, giving it
// COMMON + its role prompt + its phase addendum (see the runner section at the end, which documents the order).
export const meta = {
  name: 'pauta-build',
  description: 'Build the Pauta app. Foundations were done on Linux; resumed on Windows: phase A closes the engines, phase B builds the screens as their dependencies finish, phase C integrates, phase D reviews and fixes.',
  phases: [
    { title: 'Foundations', detail: 'ui kit and assets (done); audio+transcription and score engines (implemented, closed in phase A)' },
    { title: 'A · Engines', detail: 'engine-score tests + ABC polish, engine-audio calibration + build checks' },
    { title: 'B · Screens', detail: 'settings (deps done), library + viewer (after engine-score), capture (after both engines)' },
    { title: 'C · Integrate', detail: 'typecheck, tests, build, e2e, final screenshots light/dark, README' },
    { title: 'D · Review', detail: 'parallel reviewers that only report, then per-area fixers and a final verification' },
  ],
}

